#!/usr/bin/env bash
# Off-site backup of everything that cannot be rebuilt:
#   - the Neon database (pg_dump, custom format)
#   - the original PDFs (and, optionally, converted content — it can be regenerated by reprocessing)
# The archive is sent OUTSIDE the VM (rclone remote or rsync target) and verified there.
# A copy on the same disk is NOT a backup; the local staging copy is deleted at the end.
#
#   ./scripts/backup.sh
# Cron (daily 03:30):  30 3 * * * cd /opt/bookflow && ./scripts/backup.sh >> /var/log/bookflow-backup.log 2>&1
set -euo pipefail
cd "$(dirname "$0")/.."
set -a; . ./.env; set +a

DATA_DIR="${DATA_DIR:?DATA_DIR não definido}"
REMOTE="${BACKUP_RCLONE_REMOTE:-}"
RSYNC_TARGET="${BACKUP_RSYNC_TARGET:-}"
KEEP_DAYS="${BACKUP_KEEP_DAYS:-30}"
STAGING_ROOT="${BACKUP_STAGING_DIR:-/var/tmp/bookflow-backup}"
DB_URL="${DATABASE_MIGRATION_URL:-$DATABASE_URL}"   # pg_dump needs the direct (non-pooled) Neon endpoint
RCLONE_CONF_DIR="${RCLONE_CONFIG_DIR:-$HOME/.config/rclone}"

[ -n "$REMOTE$RSYNC_TARGET" ] || { echo "ERRO: defina BACKUP_RCLONE_REMOTE ou BACKUP_RSYNC_TARGET no .env (destino externo à VM)."; exit 1; }

stamp="$(date -u +%Y%m%dT%H%M%SZ)"
work="$STAGING_ROOT/$stamp"
mkdir -p "$work"
trap 'rm -rf "$work"' EXIT

echo "[$(date -u +%FT%TZ)] backup $stamp"

# pg_dump 17+ from the host if installed, otherwise the official (multi-arch) postgres image.
run_pg_dump() {
  local args=(--format=custom --no-owner --no-privileges)
  if command -v pg_dump >/dev/null && [ "$(pg_dump --version | grep -oE '[0-9]+' | head -1)" -ge 17 ]; then
    PGCONNECT_TIMEOUT=20 pg_dump "${args[@]}" --file="$1" "$DB_URL"
  else
    docker run --rm --network host -e PGCONNECT_TIMEOUT=20 -v "$(dirname "$1"):/out" postgres:17-alpine \
      pg_dump "${args[@]}" --file="/out/$(basename "$1")" "$DB_URL"
  fi
}

# 1) Database first: files referenced by the dump will all be in the archive taken right after.
run_pg_dump "$work/database.dump"

# 2) Files.
paths=(originals)
[ "${BACKUP_INCLUDE_CONVERTED:-false}" = "true" ] && paths+=(converted)
tar -C "$DATA_DIR" -czf "$work/files.tar.gz" "${paths[@]}"

# 3) Manifest + checksums.
{
  echo "stamp=$stamp"
  echo "host=$(hostname)"
  echo "git=$(git rev-parse --short HEAD 2>/dev/null || echo n/a)"
  echo "originals=$(find "$DATA_DIR/originals" -type f -name '*.pdf' | wc -l)"
  echo "included=${paths[*]}"
} > "$work/manifest.txt"
(cd "$work" && sha256sum database.dump files.tar.gz manifest.txt > SHA256SUMS)
du -sh "$work"/* | sed 's/^/  /'

# 4) Upload + verification at the destination.
if [ -n "$REMOTE" ]; then
  rclone() { docker run --rm --network host -v "$RCLONE_CONF_DIR:/config/rclone" -v "$work:/data:ro" rclone/rclone:1.68 "$@"; }
  rclone copy /data "$REMOTE/$stamp" --checksum
  rclone check /data "$REMOTE/$stamp" --one-way --checksum
  rclone delete "$REMOTE" --min-age "${KEEP_DAYS}d" --rmdirs || true
else
  rsync -a --checksum "$work/" "$RSYNC_TARGET/$stamp/"
  # Dry-run with checksums must report no differences.
  if [ -n "$(rsync -an --checksum --out-format='%n' "$work/" "$RSYNC_TARGET/$stamp/")" ]; then
    echo "ERRO: verificação do rsync encontrou diferenças"; exit 1
  fi
fi

mkdir -p backups
echo "$stamp $(date -u +%FT%TZ)" > backups/last-success
echo "[$(date -u +%FT%TZ)] backup $stamp concluído e verificado no destino."
